        "board_setup": board_setup,
        "board_fix_setup": board_fix_setup,
        "continue_setup": continue_setup,
        "board_safety_refresh": board_safety_refresh,
        "board_validate": board_validate,
        "get_setup_status": get_setup_status,
    }
